using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class PrestigeMetrics{public NumberData compute,income,dataRate,claim,knowledgeRate;public double trainingSpeed,researchSpeed,intWeight;public string[] slots;}
 [Serializable]public sealed class PrestigeCase{public string name,action,id,amount;public double at;public StateData before,expected;public PrestigeMetrics rates;}
 [Serializable]public sealed class PrestigeCases{public string scope;public PrestigeCase[] cases;}
 public sealed class PrestigeParityTests
 {
  static void Near(ScientificNumber a,ScientificNumber b,string name){if(b.IsZero)Assert.That(a.IsZero,Is.True,name);else Assert.That(a.Log10(),Is.EqualTo(b.Log10()).Within(2e-10),name);}
  public static void Numbers(GameState s,StateData data,string name)
  {
   var e=data.ToState();Near(s.Credits,e.Credits,name+" credits");Near(s.Data,e.Data,name+" data");Assert.That(s.Hardware,Is.EqualTo(e.Hardware),name+" hardware");Assert.That(s.Research,Is.EqualTo(e.Research),name+" research");Assert.That(s.Quality,Is.EqualTo(e.Quality),name+" quality");Assert.That(s.Efficiency,Is.EqualTo(e.Efficiency),name+" efficiency");Assert.That(s.Workshop.integration,Is.EqualTo(e.Workshop.integration),name+" integration");
   Near(s.Prestige.Eligible,e.Prestige.Eligible,name+" eligible");Near(s.Prestige.Entitlement,e.Prestige.Entitlement,name+" entitlement");Assert.That(s.Prestige.Free.CompareTo(e.Prestige.Free),Is.Zero,name+" free exact");Assert.That(s.Prestige.Cycle.CompareTo(e.Prestige.Cycle),Is.Zero,name+" cycle exact");Assert.That(s.Prestige.Spent.CompareTo(e.Prestige.Spent),Is.Zero,name+" spent exact");Assert.That(s.Prestige.Total.CompareTo(e.Prestige.Total),Is.Zero,name+" total exact");Assert.That(s.Prestige.resets,Is.EqualTo(e.Prestige.resets),name+" resets");Assert.That(s.Workshop.nodes,Is.EqualTo(e.Workshop.nodes),name+" nodes");Assert.That(s.Prestige.known,Is.EqualTo(e.Prestige.known),name+" known");Assert.That(s.Workshop.permanentSlots,Is.EqualTo(e.Workshop.permanentSlots),name+" permanent slots");Assert.That(s.Prestige.milestones,Is.EqualTo(e.Prestige.milestones),name+" run edges");
   Assert.That(s.Workshop.fragments,Is.EqualTo(e.Workshop.fragments),name+" blueprint fragments");Assert.That(s.Workshop.researchProgress,Is.EqualTo(e.Workshop.researchProgress).Within(1e-10),name+" blueprint progress");Assert.That(s.Workshop.learned,Is.EqualTo(e.Workshop.learned),name+" learned blueprints");Assert.That(s.Workshop.nextId,Is.EqualTo(e.Workshop.nextId),name+" next ID");Assert.That(s.Workshop.components,Is.EqualTo(e.Workshop.components),name+" components");Assert.That(s.Workshop.modules,Is.EqualTo(e.Workshop.modules),name+" modules");Assert.That(s.Workshop.equipped,Is.EqualTo(e.Workshop.equipped),name+" equipment");Assert.That(s.Workshop.inventory.Select(i=>i.id+":"+i.type+":"+i.rarity+":"+i.level+":"+i.forge),Is.EqualTo(e.Workshop.inventory.Select(i=>i.id+":"+i.type+":"+i.rarity+":"+i.level+":"+i.forge)),name+" inventory");
   Assert.That(s.Training?.id,Is.EqualTo(e.Training?.id),name+" active training");if(s.Training!=null){Assert.That(s.Training.required,Is.EqualTo(e.Training.required).Within(1e-7),name+" training contract");Assert.That(s.Training.done,Is.EqualTo(e.Training.done).Within(1e-7));}Assert.That(s.ResearchJob?.id,Is.EqualTo(e.ResearchJob?.id),name+" research preserved");Assert.That(s.Workshop.hasModuleJob,Is.EqualTo(e.Workshop.hasModuleJob),name+" active module");Assert.That(s.Prestige.trainingQueue.Select(t=>t.track+":"+t.level),Is.EqualTo(e.Prestige.trainingQueue.Select(t=>t.track+":"+t.level)),name+" training queue");Assert.That(s.Prestige.hardwareAuto,Is.EqualTo(e.Prestige.hardwareAuto),name+" autobuyers");Assert.That(s.Prestige.autoSeconds,Is.EqualTo(e.Prestige.autoSeconds).Within(1e-6),name+" shopping clock");Assert.That(s.Prestige.otherAutoSeconds,Is.EqualTo(e.Prestige.otherAutoSeconds).Within(1e-6),name+" other clock");Assert.That(s.Prestige.agentSeconds,Is.EqualTo(e.Prestige.agentSeconds).Within(1e-6),name+" agent clock");Assert.That(s.Prestige.researchAutoSeconds,Is.EqualTo(e.Prestige.researchAutoSeconds).Within(1e-6),name+" research clock");Assert.That(s.Prestige.resetIntent,Is.EqualTo(e.Prestige.resetIntent),name+" reset intent");Assert.That(s.Prestige.labs.Select(j=>j.id),Is.EqualTo(e.Prestige.labs.Select(j=>j.id)),name+" labs");Assert.That(s.Prestige.moduleQueue.Length,Is.EqualTo(e.Prestige.moduleQueue.Length),name+" module queue");
  }
  [Test]public void SixtyNodesIncomeLedgersEffectsAndRepeatedResetsMatchTypeScript()
  {
   var f=JsonUtility.FromJson<PrestigeCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/PrestigeReferenceCases.json")));Assert.That(PrestigeBalance.Nodes.Length,Is.EqualTo(60));foreach(var c in f.cases)
   {
    var s=c.before.ToState();var original=JsonUtility.ToJson(StateData.From(s));GameState n=s;
    switch(c.action){case "queue-train":n=PrestigeAutomation.QueueTraining(s,c.id);break;case "auto-toggle":n=PrestigeAutomation.ToggleHardware(s,Array.FindIndex(Balance.Hardware,h=>h.Id==c.id));break;case "hardware":n=Game.Buy(s,c.id);break;case "buy":n=PrestigeRules.Buy(s,c.id);break;case "earn":n=s.Copy();PrestigeRules.Earn(n,ScientificNumber.Parse(c.amount));break;case "ineligible":n=s.Copy();n.Credits=n.Credits.Add(ScientificNumber.Parse(c.amount));break;case "reset":n=PrestigeRules.Reset(s);break;case "tap":n=Game.Tap(s,s.SavedAt);break;case "train":n=Game.Train(s,c.id);break;case "research":n=Game.Research(s,c.id);break;case "advance":n=Game.Advance(s,c.at);break;case "upgrade":n=Workshop.Upgrade(s,c.id);break;case "craft":n=Workshop.CraftBatch(s,c.id,int.Parse(c.amount));break;case "module":n=Workshop.ModuleBatch(s,Array.FindIndex(ItemBalance.Modules,m=>m.Id==c.id),int.Parse(c.amount));break;}
    Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),c.name+" purity");Numbers(n,c.expected,c.name);Near(PrestigeRules.KnowledgeRate(n),ScientificNumber.FromData(c.rates.knowledgeRate),c.name+" knowledge rate");Near(Game.Compute(n),ScientificNumber.FromData(c.rates.compute),c.name+" compute");Near(Game.Income(n),ScientificNumber.FromData(c.rates.income),c.name+" income");Near(Game.DataRate(n),ScientificNumber.FromData(c.rates.dataRate),c.name+" data rate");Near(PrestigeRules.Claim(n),ScientificNumber.FromData(c.rates.claim),c.name+" claim");Assert.That(Game.WorkSpeed(n),Is.EqualTo(c.rates.trainingSpeed).Within(1e-8),c.name+" training speed");Assert.That(Game.WorkSpeed(n,true),Is.EqualTo(c.rates.researchSpeed).Within(1e-8),c.name+" research speed");Assert.That(PrestigeRules.Weight(n),Is.EqualTo(c.rates.intWeight).Within(1e-10),c.name+" INT weight");Assert.That(ItemBalance.Slots.Where((slot,i)=>Workshop.ActiveSlots(n)[i]),Is.EqualTo(c.rates.slots),c.name+" slots");Game.Validate(n);
   }
  }
  [Test]public void ResetTicketAndReloadCannotResetTwice()
  {var s=Game.New(1000);PrestigeRules.Earn(s,ScientificNumber.From(PrestigeRules.V("prestigeBaseRevenue")));long ticket=s.Prestige.revision;var n=PrestigeRules.Reset(s,ticket);Assert.That(n.Prestige.resets,Is.EqualTo(1));Assert.That(PrestigeRules.Reset(n,ticket),Is.SameAs(n));var restored=StateData.From(n).ToState();Assert.That(PrestigeRules.Reset(restored),Is.SameAs(restored));}
 }
}
